<template><q-page class="q-pa-lg"><div class="row items-center"><div><div class="page-title">Employees</div><div class="muted">Manage employee information, roles, and organizational access.</div></div><q-space/><q-btn flat icon="upload_file" label="Import employees" @click="router.push('/admin/employee-import')"/><q-btn color="primary" unelevated rounded icon="person_add" label="Add employee" @click="add"/></div><div class="row q-col-gutter-md q-mt-lg"><div class="col-12 col-md-6"><q-input v-model="search" outlined rounded dense placeholder="Search name, ID or email" clearable><template #prepend><q-icon name="search"/></template></q-input></div><div class="col-6 col-md-3"><q-select v-model="status" outlined rounded dense clearable label="Status" :options="['active','inactive']"/></div><div class="col-6 col-md-3"><q-select v-model="departmentId" outlined rounded dense clearable emit-value map-options label="Department" :options="departments" option-value="id" option-label="name"/></div></div><q-card flat bordered class="q-mt-lg"><q-table :rows="rows" :columns="columns" row-key="id" :loading="loading"><template #body-cell-employee="p"><q-td><div class="row items-center"><q-avatar color="indigo-1" text-color="primary" size="34px">{{ p.row.first_name[0] }}</q-avatar><div class="q-ml-sm"><div class="text-weight-bold">{{ p.row.first_name }} {{ p.row.last_name }}</div><div class="text-caption muted">{{ p.row.email }}</div></div></div></q-td></template><template #body-cell-is_active="p"><q-td><q-badge :color="p.row.is_active?'positive':'grey-6'" :label="p.row.is_active?'Active':'Inactive'"/></q-td></template><template #body-cell-actions="p"><q-td><q-btn flat round icon="visibility" aria-label="View employee" @click="view(p.row.id)"/></q-td></template></q-table></q-card></q-page></template>
<script setup>import {ref,watch,onMounted} from 'vue';import {useRouter} from 'vue-router';import api from '../services/api';const router=useRouter(),rows=ref([]),departments=ref([]),loading=ref(false),search=ref(''),status=ref(null),departmentId=ref(null);const columns=[{name:'employee',label:'Employee',field:'employee',align:'left'},{name:'employee_id',label:'Employee ID',field:'employee_id'},{name:'department_name',label:'Department',field:'department_name'},{name:'job_position',label:'Position',field:'job_position'},{name:'manager_name',label:'Manager',field:'manager_name'},{name:'joining_date',label:'Joining date',field:'joining_date'},{name:'is_active',label:'Status',field:'is_active'},{name:'actions',label:'',field:'actions'}];async function load(){loading.value=true;try{rows.value=(await api.get('/employees',{params:{search:search.value,status:status.value,department_id:departmentId.value}})).data.data}finally{loading.value=false}}function add(){router.push('/admin/employees/add')}function view(id){router.push(`/admin/employees/${id}`)}watch([search,status,departmentId],load);onMounted(async()=>{departments.value=(await api.get('/departments')).data.data;load()})</script>
